def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for i in range(n):
        # BFS to find shortest cycle containing i
        dist = [-1] * n
        parent = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

def is_4_colorable(n, edges):
    # Simple backtracking for coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def solve(u):
        if u == n:
            return True

        used_colors = {colors[v] for v in adj[u] if colors[v] != -1}
        for c in range(4):
            if c not in used_colors:
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False

    return solve(0)

